UPDATE ocr_record SET patient_id = #{patientId}, visit_id = IFNULL(#{visitId}, visit_id), link_time = NOW()
WHERE file_id = #{fileId} AND doctor_id = #{doctorId}
  AND (patient_id IS NULL OR patient_id = #{patientId})
  AND (#{visitId} IS NULL OR visit_id IS NULL OR visit_id = #{visitId})
  AND (visit_id IS NULL OR EXISTS (SELECT 1 FROM patient_follow_up_history prior_visit WHERE prior_visit.id = ocr_record.visit_id AND prior_visit.patient_basic_info_id = #{patientId}))
  AND EXISTS (SELECT 1 FROM patient_relation_doctor d WHERE d.patient_id = #{patientId} AND d.doctor_id = #{doctorId}
    AND d.research_type IN ())
  AND (#{visitId} IS NULL OR EXISTS (SELECT 1 FROM patient_follow_up_history v WHERE v.id = #{visitId} AND v.patient_basic_info_id = #{patientId}
    AND v.research_type IN ()))
